async students(){const r=await api('/api/students'),manage=['admin','registrar'].includes(state.user.role),heads=['Student','Student no.','Program','Year & Section','Classification','Academic status'];if(manage)heads.push('Action');$('#content').innerHTML=head('Student records','Search the official CTU student directory')+table(heads,r.map(x=>`<tr><td><b>${esc(x.first_name)} ${esc(x.last_name)}</b><span class="sub">${esc(x.email)}</span></td><td>${esc(x.student_no)}</td><td>${esc(x.program||'—')}<span class="sub">${badge(x.admission_type||'new')}</span></td><td>Year ${x.year_level} · ${esc(x.section||'TBA')}</td><td>${badge(x.enrollment_classification||'regular')}</td><td>${badge(x.academic_status)}</td>${manage?`<td><button class="btn btn-soft btn-sm" data-classification="${x.id}" data-current="${x.enrollment_classification}" data-program="${x.program_id}" data-year="${x.year_level}" data-student="${esc(x.first_name+' '+x.last_name)}">Edit academic profile</button></td>`:''}</tr>`).join(''))},
async courses(){const requests=[api('/api/programs'),api('/api/courses')];if(state.user.role==='admin')requests.push(api('/api/terms'));const [p,c,terms=[]]=await Promise.all(requests),actions=state.user.role==='admin'?'<div class="toolbar"><button class="btn btn-soft" data-modal="term">+ Academic term</button><button class="btn btn-dark" data-modal="course">+ New course</button></div>':'';$('#content').innerHTML=head('Academic setup','Programs, courses, and active academic terms',actions)+(terms.length?`<div class="card" style="margin-bottom:18px"><div class="card-head"><h3>Academic terms</h3></div><div class="card-body"><div class="term-list">${terms.map(x=>`<div><span>${badge(x.is_current?'Current':'Archived')}</span><b>${esc(x.school_year)} · ${esc(x.semester)}</b><small>${date(x.starts_on)} – ${date(x.ends_on)} · Enrollment ${x.enrollment_open?'open':'closed'}</small></div>`).join('')}</div></div></div>`:'')+`<div class="stats">${p.map(x=>`<article class="stat"><div class="stat-top">${esc(x.department_name)}</div><strong>${esc(x.code)}</strong><small>${esc(x.name)}</small></article>`).join('')}</div>`+table(['Course code','Course title','Program','Units','Year','Semester','Prerequisite'],c.map(x=>`<tr><td><b>${esc(x.code)}</b></td><td>${esc(x.title)}</td><td>${esc(x.program_code)}</td><td>${esc(x.units)}</td><td>${esc(x.year_level)}</td><td>${esc(x.semester)}</td><td>${esc(x.prerequisite||'None')}</td></tr>`).join(''))},
async blocks(){const [blocks,programs,courses,teachers]=await Promise.all([api('/api/registrar/blocks'),api('/api/programs'),api('/api/courses'),api('/api/teachers')]);state.blockData={blocks,programs,courses,teachers};$('#content').innerHTML=head('Block sections','Create complete course, teacher, room, and weekly schedule bundles','<button class="btn btn-dark" data-new-block>+ New block section</button>')+table(['Block section','Program','Type','Courses','Capacity','Status','Action'],blocks.map(x=>`<tr><td><b>${esc(x.code)}</b><span class="sub">${esc(x.school_year)} · ${esc(x.semester)}</span></td><td>${esc(x.program_code)} · Year ${x.year_level}</td><td>${badge(x.classification)}</td><td>${x.course_count}<span class="sub">${x.assignments.map(a=>esc(a.course_code)).join(', ')}</span></td><td>${x.enrolled}/${x.capacity}</td><td>${badge(x.is_active?'Active':'Inactive')}</td><td><div class="toolbar"><button class="btn btn-soft btn-sm" data-edit-block="${x.id}">Edit</button><button class="btn ${x.is_active?'btn-danger':'btn-soft'} btn-sm" data-block-status="${x.id}" data-active="${x.is_active}">${x.is_active?'Deactivate':'Activate'}</button></div></td></tr>`).join(''))},
